begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('a4000000-0000-4000-8000-000000000021','salon-a@elifora.test'),('a4000000-0000-4000-8000-000000000022','salon-b@elifora.test'),('a4000000-0000-4000-8000-000000000023','salon-worker@elifora.test'),('a4000000-0000-4000-8000-000000000024','salon-assistant@elifora.test');
insert into public.organizations(id,name,slug,base_currency) values('a4000000-0000-4000-8000-000000000001','Salon A','salon-a','TRY'),('a4000000-0000-4000-8000-000000000002','Salon B','salon-b','TRY');
insert into public.locations(id,organization_id,name,timezone) values('a4000000-0000-4000-8000-000000000011','a4000000-0000-4000-8000-000000000001','A','Europe/Istanbul'),('a4000000-0000-4000-8000-000000000012','a4000000-0000-4000-8000-000000000002','B','America/New_York');
insert into public.salon_memberships(id,organization_id,location_id,user_id,role_code,status,joined_at) values
 ('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000001',null,'a4000000-0000-4000-8000-000000000021','owner','active',now()),
 ('a4000000-0000-4000-8000-000000000112','a4000000-0000-4000-8000-000000000002',null,'a4000000-0000-4000-8000-000000000022','owner','active',now()),
 ('a4000000-0000-4000-8000-000000000113','a4000000-0000-4000-8000-000000000001',null,'a4000000-0000-4000-8000-000000000023','colorist','active',now()),
 ('a4000000-0000-4000-8000-000000000114','a4000000-0000-4000-8000-000000000001',null,'a4000000-0000-4000-8000-000000000024','assistant','active',now());
insert into public.clients(id,organization_id,full_name,phone,phone_normalized,created_by,updated_by,creation_location_id) values('a4000000-0000-4000-8000-000000000031','a4000000-0000-4000-8000-000000000001','Synthetic salon client','+905321234567','+905321234567','a4000000-0000-4000-8000-000000000021','a4000000-0000-4000-8000-000000000021','a4000000-0000-4000-8000-000000000011');
create temporary table salon_results(name text primary key,value jsonb);grant all on salon_results to authenticated;
create function pg_temp.op(q jsonb) returns jsonb language sql volatile security invoker as $$select public.salon_operation('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011',q,gen_random_uuid());$$;
create function pg_temp.book(i uuid,local_time text,m uuid default 'a4000000-0000-4000-8000-000000000111',v bigint default 0) returns jsonb language sql volatile security invoker as $$select jsonb_build_object('type','APPOINTMENT_SAVE','mutation_id',gen_random_uuid(),'id',i,'expected_version',v,'definition',jsonb_build_object('client_id','a4000000-0000-4000-8000-000000000031','service_id','a4000000-0000-4000-8000-000000000101','staff_membership_id',m,'local_start',local_time,'utc_offset_minutes',null,'scheduled_duration_minutes',null,'adjustment_reason',null,'notes',null,'status','CONFIRMED'));$$;
select set_config('request.jwt.claim.sub','a4000000-0000-4000-8000-000000000021',true);set local role authenticated;
select is(jsonb_array_length(public.salon_snapshot('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011','2026-10-12','2026-10-18')->'data'->'appointments'),0,'empty real calendar has no fabricated appointments');
insert into salon_results values('hours',pg_temp.op(jsonb_build_object('type','HOURS_SAVE','mutation_id',gen_random_uuid(),'expected_version',0,'days',(select jsonb_agg(jsonb_build_object('day',d,'closed',false,'opens',540,'closes',1080)) from generate_series(1,7) d))));
select is((select value#>>'{data,version}' from salon_results where name='hours'),'1','weekly opening hours persist');
insert into salon_results values('staff',pg_temp.op(jsonb_build_object('type','STAFF_SAVE','mutation_id',gen_random_uuid(),'membership_id','a4000000-0000-4000-8000-000000000111','expected_version',0,'definition',jsonb_build_object('display_name','Synthetic professional','active',true,'bookable',true,'working_capacity',null,'notes',null,'competencies',jsonb_build_array(jsonb_build_object('code','GENERAL_COLOR','level','INDEPENDENT')),'shifts',(select jsonb_agg(jsonb_build_object('day',d,'type','SHIFT','starts',540,'ends',1080)) from generate_series(1,7) d)))));
select is((select value#>>'{data,version}' from salon_results where name='staff'),'1','staff profile layers onto existing membership');
insert into salon_results values('otherstaff',pg_temp.op(jsonb_build_object('type','STAFF_SAVE','mutation_id',gen_random_uuid(),'membership_id','a4000000-0000-4000-8000-000000000113','expected_version',0,'definition',jsonb_build_object('display_name','Synthetic second professional','active',true,'bookable',true,'working_capacity',null,'notes',null,'competencies',jsonb_build_array(jsonb_build_object('code','GENERAL_COLOR','level','ASSISTED')),'shifts',(select jsonb_agg(jsonb_build_object('day',d,'type','SHIFT','starts',540,'ends',1080)) from generate_series(1,7) d)))));
insert into salon_results values('resource',pg_temp.op('{"type":"RESOURCE_SAVE","mutation_id":"a4000000-0000-4000-8000-000000000201","id":"a4000000-0000-4000-8000-000000000102","expected_version":0,"definition":{"name":"Synthetic chair","type":"CHAIR","capacity":1,"active":true}}'));
select is((select value#>>'{data,version}' from salon_results where name='resource'),'1','physical resource capacity persists');
insert into salon_results values('service_command',jsonb_build_object('type','SERVICE_SAVE','mutation_id',gen_random_uuid(),'id','a4000000-0000-4000-8000-000000000101','expected_version',0,'definition',jsonb_build_object('name','Synthetic salon color','category','COLOR','description',null,'organization_wide',false,'base_duration_minutes',60,'buffer_before_minutes',5,'buffer_after_minutes',10,'base_price',1000,'tax_rate',20,'tax_inclusive',false,'requires_colorlab',true,'requires_hair_passport',true,'requires_precheck',true,'active',true,'eligible_membership_ids',jsonb_build_array('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000113'),'capabilities',jsonb_build_array(jsonb_build_object('code','GENERAL_COLOR','level','INDEPENDENT')),'resources',jsonb_build_array(jsonb_build_object('type','CHAIR','units',1)))));
select is(pg_temp.op((select value from salon_results where name='service_command'))#>>'{data,version}','1','service duration price eligibility and requirements persist');
insert into salon_results values('command',pg_temp.book('a4000000-0000-4000-8000-000000000301','2026-10-12T10:00'));
insert into salon_results values('booked',pg_temp.op((select value from salon_results where name='command')));
select is((select value#>>'{data,status}' from salon_results where name='booked'),'CONFIRMED','eligible staff and resources create real appointment');
select is((select value#>>'{data,start_at}' from salon_results where name='booked'),'2026-10-12T07:00:00+00:00','location timezone converts wall time to UTC');
select is((select (value#>>'{data,quoted_total}')::numeric from salon_results where name='booked'),1200::numeric,'price and tax quote come from authoritative service');
select is((select (value#>>'{data,scheduled_duration_minutes}')::integer from salon_results where name='booked'),60,'catalog supplies default duration');
select is(pg_temp.op((select value from salon_results where name='command')),(select value from salon_results where name='booked'),'exact network retry returns permanent receipt');
select is((select count(*) from public.salon_appointments),1::bigint,'retry never duplicates appointment');
select is(pg_temp.op(jsonb_set((select value from salon_results where name='command'),'{definition,notes}','"Changed retry"'))->>'code','SALON_CONFLICT','changed payload under idempotency key conflicts');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-12T10:30'))->>'code','STAFF_DOUBLE_BOOKED','overlapping staff reservations are rejected');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-12T11:05'))->>'code','STAFF_DOUBLE_BOOKED','buffer time is part of occupancy');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-12T10:00','a4000000-0000-4000-8000-000000000113'))->>'code','TECHNICAL_ESCALATION','permission does not supply independent technical competency');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-12T10:00','a4000000-0000-4000-8000-000000000114'))->>'code','STAFF_NOT_ELIGIBLE','staff eligibility cannot be silently bypassed');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-12T08:00'))->>'code','OUTSIDE_WORKING_HOURS','location opening hours include buffers');
select is(pg_temp.op(jsonb_set(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-12T14:00'),'{definition,scheduled_duration_minutes}','90'))->>'code','INVALID_DURATION','duration adjustment needs an explicit reason');
select is(pg_temp.op(jsonb_set(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-12T14:00'),'{definition,base_price}','1'))->>'code','VALIDATION_FAILED','forged appointment price cannot enter the DB RPC');
select is(pg_temp.op('{"type":"RESOURCE_SAVE","mutation_id":"a4000000-0000-4000-8000-000000000202","id":"a4000000-0000-4000-8000-000000000102","expected_version":1,"definition":{"name":"Synthetic chair","type":"CHAIR","capacity":1,"active":false}}')->>'code','RESOURCE_HAS_BOOKINGS','booked resources cannot disappear');
select is(pg_temp.op(jsonb_build_object('type','EXCEPTION_SAVE','mutation_id',gen_random_uuid(),'id','a4000000-0000-4000-8000-000000000401','expected_version',0,'date','2026-10-29','reason','Synthetic holiday closure','active',true,'closed',true,'opens',null,'closes',null))#>>'{data,version}','1','dated closure persists');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-29T14:00'))->>'code','LOCATION_CLOSED','date exception overrides weekly opening');
select is(pg_temp.op(jsonb_build_object('type','AVAILABILITY_SAVE','mutation_id',gen_random_uuid(),'id','a4000000-0000-4000-8000-000000000402','expected_version',0,'membership_id','a4000000-0000-4000-8000-000000000111','type_of_absence','LEAVE','starts_at','2026-10-13T00:00:00+03:00','ends_at','2026-10-14T00:00:00+03:00','reason','Synthetic leave','active',true))#>>'{data,version}','1','time off persists');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-13T14:00'))->>'code','STAFF_UNAVAILABLE','leave blocks reservation');
select ok(jsonb_array_length(public.salon_slots('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011',jsonb_build_object('client_id','a4000000-0000-4000-8000-000000000031','service_id','a4000000-0000-4000-8000-000000000101','staff_membership_id','a4000000-0000-4000-8000-000000000111','from_date','2026-10-12','to_date','2026-10-12','duration_minutes',null,'limit',3))->'data'->'slots')=3,'bounded alternatives return real availability');
select is(public.salon_slots('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011','{"client_id":"a4000000-0000-4000-8000-000000000031","service_id":"a4000000-0000-4000-8000-000000000101","staff_membership_id":"a4000000-0000-4000-8000-000000000111","from_date":"2026-10-12","to_date":"2026-12-12","duration_minutes":null,"limit":3}')->>'code','VALIDATION_FAILED','unbounded alternative date search rejected');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000301','2026-10-12T14:00', 'a4000000-0000-4000-8000-000000000111',0))->>'code','SALON_CONFLICT','stale edit never last-write-wins');
select is(pg_temp.op(jsonb_build_object('type','APPOINTMENT_TRANSITION','mutation_id',gen_random_uuid(),'id','a4000000-0000-4000-8000-000000000301','expected_version',1,'status','COMPLETED','reason','Synthetic invalid transition'))->>'code','INVALID_TRANSITION','completion cannot skip arrival and service');
select is(pg_temp.op(jsonb_build_object('type','APPOINTMENT_TRANSITION','mutation_id',gen_random_uuid(),'id','a4000000-0000-4000-8000-000000000301','expected_version',1,'status','CANCELLED','reason','Synthetic cancellation'))#>>'{data,status}','CANCELLED','cancellation is an explicit audited transition');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000301','2026-10-12T14:00','a4000000-0000-4000-8000-000000000111',2))->>'code','APPOINTMENT_IMMUTABLE','cancelled history is immutable');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000302','2026-10-12T10:00'))#>>'{data,status}','CONFIRMED','cancellation releases resource and staff capacity');
select throws_ok($$insert into public.salon_resources(id,organization_id,location_id,name,type,capacity,active,version,created_at,updated_at,created_by,updated_by) values(gen_random_uuid(),'a4000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000011','Forged','CHAIR',1,true,1,now(),now(),auth.uid(),auth.uid())$$,'42501',null,'normal application role cannot directly write operational tables');
select throws_ok($$delete from public.salon_operation_versions$$,'42501',null,'normal role cannot delete technical appointment history');
select set_config('request.jwt.claim.sub','a4000000-0000-4000-8000-000000000024',true);
select is((select count(*) from public.salon_appointments),2::bigint,'same-salon viewer can read permitted appointments');
select is(public.salon_operation('a4000000-0000-4000-8000-000000000114','a4000000-0000-4000-8000-000000000011',pg_temp.book('a4000000-0000-4000-8000-000000000303','2026-10-12T16:00'),gen_random_uuid())->>'code','FORBIDDEN','viewer cannot create appointment');
select set_config('request.jwt.claim.sub','a4000000-0000-4000-8000-000000000022',true);
select is((select count(*) from public.salon_appointments),0::bigint,'other salon appointments read denied by RLS');
select is((select count(*) from public.salon_services),0::bigint,'other salon service catalog read denied');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000303','2026-10-12T16:00'))->>'code','TENANT_CONTEXT_INVALID','foreign membership is not authorization');
reset role;
select ok((select count(*) from public.audit_events where organization_id='a4000000-0000-4000-8000-000000000001' and action='salon.appointment_save')=2,'exact retry creates no duplicate booking audit');
select ok((select count(*) from public.salon_operation_versions where organization_id='a4000000-0000-4000-8000-000000000001' and entity_id='a4000000-0000-4000-8000-000000000301')=2,'immutable versions preserve creation and cancellation');
set local role elifora_salon_writer;select set_config('request.jwt.claim.sub','a4000000-0000-4000-8000-000000000021',true);
select throws_ok($$select app_private.salon_local_instant('2026-03-08T02:30','America/New_York',null)$$,'22007','INVALID_LOCAL_TIME','DST missing wall time rejected');
select throws_ok($$select app_private.salon_local_instant('2026-11-01T01:30','America/New_York',null)$$,'22007','AMBIGUOUS_LOCAL_TIME','DST repeated wall time requires an explicit offset');
select is(app_private.salon_local_instant('2026-11-01T01:30','America/New_York',-240),'2026-11-01T05:30:00Z'::timestamptz,'explicit daylight offset selects the correct instant');
select is(app_private.salon_local_instant('2026-11-01T01:30','America/New_York',-300),'2026-11-01T06:30:00Z'::timestamptz,'explicit standard offset selects the other instant');
reset role;update public.salon_memberships set status='revoked',revoked_at=now() where id='a4000000-0000-4000-8000-000000000111';
set local role authenticated;select set_config('request.jwt.claim.sub','a4000000-0000-4000-8000-000000000021',true);
select is((select count(*) from public.salon_appointments),0::bigint,'revoked membership hides former appointments');
select is(pg_temp.op(pg_temp.book('a4000000-0000-4000-8000-000000000303','2026-10-12T16:00'))->>'code','MEMBERSHIP_REVOKED','revoked membership cannot write');
reset role;set local role anon;
select throws_ok($$select public.salon_snapshot('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011','2026-10-12','2026-10-18')$$,'42501',null,'anonymous operation denied');
reset role;set local role service_role;
select throws_ok($$select public.salon_operation('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011','{}',gen_random_uuid())$$,'42501',null,'service-role is not an appointment mutation bypass');
select * from finish();rollback;
